insert into equipo (campo_id, codigo, nombre, sistema, clase_iso, criticidad, servicio, modo_falla, norma, intervencion_ubicacion, intervencion_accion, intervencion_avisar_a, aguas_abajo, redundancia, distribucion_falla) values ('ceiba', 'P-201B', 'Bomba multietapa de transferencia de agua', 'Tratamiento de agua', 'bomba-centrifuga', 5, null, 'Lubricación de cojinete', 'Centrífuga multietapa · API 610, Tabla 8: vibración en la caja de rodamientos.', 'Batería 1 · tren de agua', 'Llevar P-201A y P-201C a su caudal máximo y confirmar el nivel del tanque de agua antes de intentar el arranque: si ya está alto, cerrar primero los pozos con menos crudo por barril de agua.', 'Supervisor de operaciones e ingeniería de producción', null, null, '{"reparto":[["Mecánicas",44.1],["Eléctricas",27.7],["Operacionales y de sistema",25.4],["Diseño",2.4]],"fuente":"Reparto de bombeo en campo Sirte (Libia), 673 elementos de falla clasificados."}'::jsonb);
